 static float StateNumberK(object? state,string name){if(state==null)return 0;object? value=state.GetType().GetProperty(name)?.GetValue(state)??state.GetType().GetField(name)?.GetValue(state);return value is float f?f:value is double d?(float)d:value is int n?n:0;}
 static bool StateFlagK(object? state,string name)=>state?.GetType().GetProperty(name)?.GetValue(state) is true||state?.GetType().GetField(name)?.GetValue(state) is true;
 void ToggleFlightK(FittingModule m){if(world.InWarp){world.Say("Module activation unavailable in warp.");return;}switch(m.Kind){case "weapon":world.ToggleWeapon(m.Index);break;case "ewar":world.ToggleEwar(m.Index);break;case "defense":world.ToggleDefense(m.Index);break;case "support":world.ToggleSupport(m.Index);break;case "enhancement":world.ToggleEnhancement(m.Index);break;case "mobility":world.ToggleMobility(m.Index);break;case "utility":world.ToggleUtility(m.Index);break;case "special":world.ToggleSpecial(m.Index);break;case "legacy":if(world.Player.UtilityFit=="miner")world.ToggleMining();else if(world.Player.UtilityFit=="salvager")world.ToggleSalvager();else StartHack();break;}}
 void FlightModuleMenuK(FittingModule m){var state=world.Player.TacticalModule(m);var actions=new List<(string,Action)>{("Show info",()=>ShowItemInfo(m.Id)),(m.Active?"Deactivate":"Activate",()=>ToggleFlightK(m)),("Show fitted ship attributes",ShowCurrentShipInfo)};if(state?.GetType().GetProperty("Overheat")!=null||state?.GetType().GetField("Overheat")!=null)actions.Add((StateFlagK(state,"Overheat")?"Stop overload":"Overload module",()=>world.SetModuleOverheat(m,!StateFlagK(state,"Overheat"))));if(m.Payload.Length>0&&m.Kind=="weapon")actions.Add(("Reload current ammunition",()=>world.ReloadWeapon(m.Index)));foreach(string payload in FitPayloads(m)){string id=payload;actions.Add(("Load "+DemoWorld.ItemName(id)+" / available "+world.ItemCount(id,false),()=>{if(m.Kind=="weapon")world.LoadWeapon(m.Index,id);else if(m.Kind=="ewar")world.LoadEwarPayload(m.Index,id);else if(m.Kind=="defense")world.LoadDefensePayload(m.Index,id);else if(m.Kind=="support")world.LoadSupportPayload(m.Index,id);else if(m.Kind=="utility")world.LoadUtilityPayload(m.Index,id,false);else if(m.Kind=="enhancement")world.LoadEnhancementScript(m.Index,id);}));}ShowPopup(m.Name,actions);}
 void DrawFlightRackK(){LoadPreferencesK();var ship=world.Player;string hull=ship.InstanceId;var installed=FittingLayoutModel.Installed(ship).Where(m=>m.Bank!="rig").ToArray();if(!preferencesK.Racks.TryGetValue(hull,out var rack))preferencesK.Racks[hull]=rack=new();rack.Reconcile(installed);flightHitsK.Clear();int maximum=Math.Max(8,rack.Positions.Values.DefaultIfEmpty(0).Max()+1),pages=(maximum+7)/8;rackPageK=Math.Clamp(rackPageK,0,pages-1);string[] banks=["high","medium","low"];for(int b=0;b<3;b++){string bank=banks[b];int y=710+b*54;ui.Text(bank=="medium"?"MID":bank.ToUpper(),850,y-9,Muted,9);ui.Text(ship.RackHeat[b].ToString("P0"),850,y+5,ship.RackHeat[b]>.7f?Red:Gold,9);for(int i=0;i<8;i++){int position=i+rackPageK*8;var at=new Vector2(915+i*43,y);var m=installed.FirstOrDefault(m=>m.Bank==bank&&rack.Position(m)==position);bool exists=position<FittingLayoutModel.Capacity(ship,bank)||m!=null;ui.Circle(at,19,exists?new Color(45,61,69):new Color(22,30,35),3);if(m==null){if(exists)ui.Center((position+1).ToString(),at.X,at.Y-5,Muted,9);continue;}var module=m;var state=ship.TacticalModule(m);float reload=StateNumberK(state,"ReloadLeft"),remaining=Math.Max(StateNumberK(state,"Cooldown"),StateNumberK(state,"CycleLeft")),cycle=StateNumberK(state,"CycleDuration");if(cycle<=0)cycle=StateNumberK(state,"Cycle");if(cycle<=0&&WeaponCatalog.ById.TryGetValue(m.Id,out var weapon))cycle=weapon.Cycle;if(cycle<=0)cycle=5;Color color=m.Burnt?Red:m.Online==false?Muted:reload>0?Gold:m.Active?Green:Cyan;ui.Circle(at,16,color,1);if(m.Active||reload>0)ui.Arc(at,22,-MathF.PI/2,MathF.Tau*Math.Clamp((reload>0?reload:remaining)/Math.Max(.1f,cycle),0,1),color,2);if(StateFlagK(state,"Overheat"))ui.Arc(at,19,-MathF.PI,MathF.PI,Red,3);ui.Center(FitAbbreviation(m.Kind),at.X,at.Y-6,color,12);ui.Center(m.Payload.Length>0?m.Loaded.ToString():"",at.X,at.Y+8,White,8);if(m.Payload.Length>0)ui.Bar(new((int)at.X-16,y+25,32,3),FitChargeFraction(m),Gold);var rect=new Rectangle((int)at.X-20,y-20,40,40);ui.Hits.Add(new(rect,()=>ToggleFlightK(module),$"Flight slot / {bank} {position+1} / {m.Name} / {(m.Burnt?"burnt":m.Online==false?"offline":reload>0?$"reload {reload:0.0}s":m.Active?"active":"online")} / ammo {m.Loaded} / damage {StateNumberK(state,"Damage"):P0}"));flightHitsK.Add((rect,m));}}if(pages>1)ui.Button(new(1110,680,130,24),$"RACK {rackPageK+1}/{pages}",()=>rackPageK=(rackPageK+1)%pages);}
 void DrawTargetsK(){var ids=world.RetainedLocks.Select(l=>l.Id).Append(world.LockedId).Where(id=>id.Length>0).Distinct().ToArray();int index=0;foreach(string id in ids){var t=world.Targets.FirstOrDefault(t=>t.Id==id&&t.Alive);if(t==null)continue;var target=t;int x=420+index%4*199,y=15+index/4*102;ui.Panel(new(x,y,190,95),ShortInfo(t.Name,23));ui.Button(new(x+5,y+31,180,55),"",()=>{world.SelectedId=target.Id;world.LockedId=target.Id;},"Locked target / "+t.Id,world.LockedId==t.Id);ui.Text(SolarCatalog.Distance(Vector3.Distance(t.Position,world.Player.Position)),x+10,y+40,Muted,10);ui.Bar(new(x+10,y+58,167,4),t.Shield/(t.Profile?.MaxShield??100),Cyan);ui.Bar(new(x+10,y+66,167,4),t.Armor/(t.Profile?.MaxArmor??70),Gold);ui.Bar(new(x+10,y+74,167,4),t.Hull/(t.Profile?.MaxHull??65),Red);ui.Button(new(x+164,y+5,20,18),"x",()=>world.UnlockEnhancedTarget(target.Id),"Unlock target / "+t.Id);index++;}foreach(var pending in world.Acquisitions.Take(4)){ui.Text("Locking "+ShortInfo(world.Targets.FirstOrDefault(t=>t.Id==pending.Id)?.Name??pending.Id,25)+$" / {pending.Left:0.0}s",420,330+world.Acquisitions.IndexOf(pending)*21,Gold,11);}}
 void DrawSelectedK(){int x=1260,y=15;ui.Panel(new(x,y,325,167),"Selected item");var r=AllOverviewRowsK().FirstOrDefault(r=>r.Id==world.SelectedId);ui.Text(r==null?"No object selected":ShortSpace(r.Name,35),x+13,y+36,White,14);ui.Text(r==null?"Choose an overview row or space bracket":SolarCatalog.Distance(r.Distance)+" / "+ShortSpace(r.Type,26),x+13,y+59,Muted,12);string[] icons=[">",">|","W","O","K","+","EYE","TRK","i"];string[] tips=["Approach selected","Align to selected","Warp / dock / jump / open","Orbit selected","Keep at range","Lock / unlock target","Look at selected","Track selected","Show object information"];for(int i=0;i<9;i++){int action=i;ui.Button(new(x+12+i*34,y+87,30,32),icons[i],()=>{if(r==null){world.Say("Select an object first.");return;}SpaceAction(action,r.Id);},tips[i]);}ui.Text(world.InWarp?"WARP DRIVE ACTIVE":world.Transit!=null?"Establishing warp vector":world.RetainedLocks.Any(l=>l.Id==world.SelectedId)?"Target lock acquired":r?.Local==false?"Remote celestial / warp available":"Ready for command",x+13,y+136,Muted,11);}
